import React, { useState, useEffect } from 'react';
import './App.css';

function App() {
  const [pantalla, setPantalla] = useState('catalogo'); 
  const [productos, setProductos] = useState([]);

  const [ventasDelDia, setVentasDelDia] = useState(() => {
    const guardadas = localStorage.getItem('ventas_paisita');
    return guardadas ? JSON.parse(guardadas) : [];
  });

  const [fechaHoy] = useState(() => {
    return new Date().toLocaleDateString('es-CO', { 
      weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' 
    });
  });

  const [nombre, setNombre] = useState('Empanada');
  const [categoria, setCategoria] = useState('Fritos');
  const [imagenUrl, setImagenUrl] = useState('https://images.unsplash.com/photo-1628102477218-097561f38e6f?q=80&w=300&auto=format&fit=crop');
  const [precioCosto, setPrecioCosto] = useState(1500);
  const [impuesto, setImpuesto] = useState('19'); 
  const [precioVenta, setPrecioVenta] = useState(2500);
  const [stock, setStock] = useState(20);

  useEffect(() => {
    localStorage.setItem('ventas_paisita', JSON.stringify(ventasDelDia));
  }, [ventasDelDia]);

  useEffect(() => {
    obtenerInventarioBackend();
  }, []);

  const obtenerInventarioBackend = async () => {
    try {
      const respuesta = await fetch('http://localhost:8080/api/productos');
      if (respuesta.ok) {
        const datos = await respuesta.json();
        setProductos(datos);
      }
    } catch (error) {
      console.error("Error al sincronizar con Spring Boot:", error);
    }
  };

  const handleBorrarTodo = async () => {
    if (window.confirm("🚨 ¿ATENCIÓN! ¿Estás seguro de que deseas ELIMINAR TODOS los productos de la base de datos?")) {
      try {
        const respuesta = await fetch('http://localhost:8080/api/productos/vaciar', {
          method: 'DELETE'
        });
        if (respuesta.ok) {
          alert("Base de datos vaciada con éxito.");
          setProductos([]);
          setVentasDelDia([]);
          localStorage.removeItem('ventas_paisita');
        } else {
          alert("Error del servidor al borrar: " + respuesta.status);
        }
      } catch (error) {
        alert("Error de conexión: Verifica que Spring Boot esté encendido.");
        console.error(error);
      }
    }
  };

  const cambiarStockManual = async (producto) => {
    const nuevoStockString = prompt(`Modificar existencias de: ${producto.nombre}\nCantidad actual: ${producto.stock} uds.\nEscribe el nuevo stock total:`, producto.stock);
    if (nuevoStockString === null) return; 

    const nuevoStockNum = parseInt(nuevoStockString, 10);
    if (isNaN(nuevoStockNum) || nuevoStockNum < 0) return alert("Cantidad inválida.");

    const productoActualizado = { ...producto, stock: nuevoStockNum };

    try {
      const respuesta = await fetch('http://localhost:8080/api/productos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(productoActualizado)
      });
      if (respuesta.ok) obtenerInventarioBackend();
    } catch (error) {
      alert("Error al actualizar stock.");
    }
  };

  const handleGuardar = async (e) => {
    e.preventDefault();
    const productoExistente = productos.find((p) => p.nombre.toLowerCase().trim() === nombre.toLowerCase().trim());
    if (productoExistente) {
      alert("El producto ya existe. Usa el botón 'Stock' en su tarjeta para modificarlo.");
      return;
    }

    const nuevoProducto = {
      nombre: nombre.trim(),
      categoria,
      imagenUrl,
      precioCosto: parseFloat(precioCosto || 0),
      impuesto: parseFloat(impuesto || 0),
      precioVenta: parseFloat(precioVenta || 0),
      stock: parseInt(stock || 0)
    };

    try {
      const respuesta = await fetch('http://localhost:8080/api/productos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(nuevoProducto)
      });
      if (respuesta.ok) {
        alert("Producto añadido.");
        obtenerInventarioBackend();
        setPantalla('catalogo');
      }
    } catch (error) {
      alert("Error de conexión.");
    }
  };

  const registrarVenta = (producto) => {
    if (producto.stock <= 0) return alert("¡Agotado!");

    const inventarioActualizado = productos.map((p) => p.id === producto.id ? { ...p, stock: p.stock - 1 } : p);
    setProductos(inventarioActualizado);

    const cCosto = producto.precioCosto || 0;
    const cImpuesto = producto.impuesto || 0;
    const costoRealConIva = cCosto * (1 + cImpuesto / 100);
    const gananciaNeta = (producto.precioVenta || 0) - costoRealConIva;

    const nuevaVenta = {
      id: Date.now(),
      nombre: producto.nombre,
      precioVenta: producto.precioVenta || 0,
      costoConIva: costoRealConIva,
      gananciaNeta: gananciaNeta,
      hora: new Date().toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit' })
    };
    setVentasDelDia([...ventasDelDia, nuevaVenta]);
  };

  const formatearMoneda = (v) => new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', minimumFractionDigits: 0 }).format(v || 0);

  const ingresosTotales = ventasDelDia.reduce((sum, v) => sum + v.precioVenta, 0);
  const gananciasTotalesNetas = ventasDelDia.reduce((sum, v) => sum + v.gananciaNeta, 0);

  return (
    <div className="app-layout">
      <header className="app-header">
        <div className="header-brand">
          <h1>El Paisita UP</h1>
          <p className="fecha-badge">📅 {fechaHoy}</p>
        </div>
        <nav className="header-nav">
          <button className={`nav-link ${pantalla === 'catalogo' ? 'active' : ''}`} onClick={() => setPantalla('catalogo')}>📦 Catálogo</button>
          <button className={`nav-link ${pantalla === 'formulario' ? 'active' : ''}`} onClick={() => setPantalla('formulario')}>➕ Ingresar</button>
          <button className={`nav-link-alert ${pantalla === 'reporte' ? 'active' : ''}`} onClick={() => setPantalla('reporte')}>📊 Caja ({ventasDelDia.length})</button>
          <button className="btn-nav-clear-database" onClick={handleBorrarTodo}>🔥 Reiniciar</button>
        </nav>
      </header>

      <main className="app-content">
        {pantalla === 'catalogo' && (
          <div className="catalogo-view">
            <div className="seccion-titulo">
              <h2>Inventario Disponible</h2>
              <p>Monitoreo y facturación directa.</p>
            </div>
            <div className="grid-catalogo">
              {productos.map((prod) => (
                <div key={prod.id} className="card-producto">
                  <div className="card-image-wrapper">
                    <img src={prod.imagenUrl} alt={prod.nombre} onError={(e)=>{e.target.src="https://images.unsplash.com/photo-1546069901-ba9599a7e63c"}} />
                    <span className="categoria-tag">{prod.categoria}</span>
                  </div>
                  <div className="card-info">
                    <h3>{prod.nombre}</h3>
                    <div className="card-precios">
                      <div>
                        <span className="label-precio">Venta</span>
                        <span className="valor-venta">{formatearMoneda(prod.precioVenta)}</span>
                      </div>
                      <div className="text-right">
                        <span className="label-precio">Costo base</span>
                        <span className="valor-costo">{formatearMoneda(prod.precioCosto)}</span>
                      </div>
                    </div>
                    <div className="stock-status-bar">
                      <span className="stock-count">Stock: <strong>{prod.stock} uds</strong></span>
                      <div className="progreso-stock" style={{width: `${Math.min((prod.stock/50)*100, 100)}%`, backgroundColor: prod.stock < 5 ? '#E8C5C8' : '#C1D7C3'}}></div>
                    </div>
                    <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '8px' }}>
                      <button className="btn-vender-card" onClick={() => registrarVenta(prod)} disabled={prod.stock <= 0}>
                        {prod.stock <= 0 ? '🚫 Agotado' : '🛒 Vender'}
                      </button>
                      <button className="btn-modificar-stock" onClick={() => cambiarStockManual(prod)}>✏️ Stock</button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {pantalla === 'formulario' && (
          <div className="form-container-centered">
            <div className="form-card">
              <form onSubmit={handleGuardar}>
                <div className="form-group"><label className="form-label">Nombre</label><input type="text" value={nombre} onChange={(e) => setNombre(e.target.value)} className="form-input" required /></div>
                <div className="grid-2-col">
                  <div className="form-group"><label className="form-label">Categoría</label><input type="text" value={categoria} onChange={(e) => setCategoria(e.target.value)} className="form-input" /></div>
                  <div className="form-group"><label className="form-label">Imagen URL</label><input type="text" value={imagenUrl} onChange={(e) => setImagenUrl(e.target.value)} className="form-input" /></div>
                </div>
                <div className="grid-2-col">
                  <div className="form-group"><label className="form-label">Precio Costo</label><input type="number" value={precioCosto} onChange={(e) => setPrecioCosto(Number(e.target.value))} className="form-input" /></div>
                  <div className="form-group"><label className="form-label">Impuesto %</label><input type="number" value={impuesto} onChange={(e) => setImpuesto(e.target.value)} className="form-input" /></div>
                </div>
                <div className="grid-2-col">
                  <div className="form-group"><label className="form-label">Precio Venta</label><input type="number" value={precioVenta} onChange={(e) => setPrecioVenta(Number(e.target.value))} className="form-input" /></div>
                  <div className="form-group"><label className="form-label">Stock Inicial</label><input type="number" value={stock} onChange={(e) => setStock(Number(e.target.value))} className="form-input" /></div>
                </div>
                <button type="submit" className="btn-submit">Guardar Producto</button>
              </form>
            </div>
          </div>
        )}

        {pantalla === 'reporte' && (
          <div className="reporte-view">
            <div className="kpi-dashboard">
              <div className="kpi-card text-pastel-pink"><h3>Ventas</h3><p className="kpi-valor">{ventasDelDia.length}</p></div>
              <div className="kpi-card text-pastel-blue"><h3>Caja</h3><p className="kpi-valor">{formatearMoneda(ingresosTotales)}</p></div>
              <div className="kpi-card text-pastel-green"><h3>Utilidad</h3><p className="kpi-valor">{formatearMoneda(gananciasTotalesNetas)}</p></div>
            </div>
            <div className="form-card full-width-card">
              <div className="reporte-header"><h2>Bitácora</h2><button className="btn-clean-caja" onClick={() => setVentasDelDia([])}>🔒 Cerrar Caja</button></div>
              <table className="tabla-reporte">
                <thead><tr><th>Hora</th><th>Ítem</th><th>Precio</th><th>Ganancia</th></tr></thead>
                <tbody>
                  {ventasDelDia.map((v) => (
                    <tr key={v.id}><td>{v.hora}</td><td>{v.nombre}</td><td>{formatearMoneda(v.precioVenta)}</td><td>{formatearMoneda(v.gananciaNeta)}</td></tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
